    mr0, mr1 = min(r for r, c in marker), max(r for r, c in marker)
    mc0, mc1 = min(c for r, c in marker), max(c for r, c in marker)
    pattern = [row[mc0:mc1 + 1] for row in grid[mr0:mr1 + 1]]
    pattern = [list(row) for row in zip(*pattern[::-1])]

    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    ph, pw = len(pattern), len(pattern[0])
    sh, sw = (r1 - r0 + 1) // ph, (c1 - c0 + 1) // pw

    for i in range(ph):
        for j in range(pw):
            color = pattern[i][j]
            if color:
                for r in range(r0 + i * sh, r0 + (i + 1) * sh):
                    for c in range(c0 + j * sw, c0 + (j + 1) * sw):
                        if grid[r][c] == 8:
                            out[r][c] = color
    return out
